To solve this problem, we need to find the number of ways to place `n` non-attacking queens on an `n x n` chessboard. This is a classic backtracking problem where we need to ensure that no two queens threaten each other. The solution involves recursively placing queens row by row and checking for conflicts with previously placed queens.

Here is the Python function that implements this solution:

```python
def n_queens(n: int) -> int:
    def is_safe(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row][i] == 1:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        return True

    def solve(n, col, board, res):
        if col == n:
            res[0] += 1
            return

        for i in range(n):
            if is_safe(board, i, col):
                board[i][col] = 1
                solve(n, col + 1, board, res)
                board[i][col] = 0

    res = [0]
    board = [[0 for _ in range(n)] for _ in range(n)]
    solve(n, 0, board, res)
    return res[0]
```

