    result = []
    start = nums[0]
    prev = nums[0]

    for num in nums[1:]:
        if num == prev + 1:
            prev = num
        else:
            if start == prev:
                result.append(str(start))
            else:
                result.append(f"{start}-{prev}")
            start = num
            prev = num

    # Handle the last run
    if start == prev:
        result.append(str(start))
    else:
        result.append(f"{start}-{prev}")

    return result
```

